-- ============================================================================
-- Testimonials + Transfer Certificates - SCHEMA (POSTGRESQL)
-- Creates the "Testimonials" and "TransferCertificates" tables. IDEMPOTENT
-- (CREATE TABLE IF NOT EXISTS). Fresh databases get these from the EF model via
-- EnsureCreated; this script is for existing databases. FK targets "Student"."Id".
-- ============================================================================

CREATE TABLE IF NOT EXISTS "Testimonials" (
    "Id"            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId"     integer NULL,
    "StudentName"   character varying(150) NOT NULL,
    "Designation"   character varying(150) NULL,
    "Content"       text NOT NULL,
    "Photo"         text NULL,
    "DisplayOrder"  integer NOT NULL DEFAULT 0,
    "Status"        boolean NOT NULL DEFAULT true,
    "IsPublished"   boolean NOT NULL DEFAULT false,
    "CreatedBy"     text NULL,
    "CreatedAt"     timestamp without time zone NOT NULL,
    "EditedBy"      text NULL,
    "EditedAt"      timestamp without time zone NOT NULL,
    "MACAddress"    text NULL,
    CONSTRAINT "FK_Testimonials_Student" FOREIGN KEY ("StudentId")
        REFERENCES "Student"("Id") ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS "IX_Testimonials_StudentId" ON "Testimonials"("StudentId");

CREATE TABLE IF NOT EXISTS "TransferCertificates" (
    "Id"                    integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId"             integer NOT NULL,
    "CertificateNo"         character varying(50) NOT NULL,
    "IssueDate"             timestamp without time zone NOT NULL,
    "LeavingDate"           timestamp without time zone NULL,
    "Reason"                character varying(500) NULL,
    "Conduct"               character varying(500) NULL,
    "Remarks"               character varying(1000) NULL,
    "Status"                integer NOT NULL DEFAULT 0,
    "StudentNameSnapshot"   text NULL,
    "UniqueIdSnapshot"      text NULL,
    "ClassNameSnapshot"     text NULL,
    "ClassRollSnapshot"     integer NOT NULL DEFAULT 0,
    "SessionNameSnapshot"   text NULL,
    "AdmissionDateSnapshot" timestamp without time zone NULL,
    "CreatedBy"             text NULL,
    "CreatedAt"             timestamp without time zone NOT NULL,
    "EditedBy"              text NULL,
    "EditedAt"              timestamp without time zone NOT NULL,
    "MACAddress"            text NULL,
    CONSTRAINT "FK_TransferCertificates_Student" FOREIGN KEY ("StudentId")
        REFERENCES "Student"("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TransferCertificates_CertificateNo" ON "TransferCertificates"("CertificateNo");
CREATE INDEX IF NOT EXISTS "IX_TransferCertificates_StudentId" ON "TransferCertificates"("StudentId");
